// --- Antigravity Client-Side Database Mock (for static deployments like GitHub Pages) ---
(() => {
  const originalFetch = window.fetch;
  
  let firebaseApp = null;
  let firestoreDb = null;
  let firebaseInitialized = false;

  const initFirebase = async () => {
    if (firebaseInitialized) return;
    firebaseInitialized = true;
    
    const config = window.FIREBASE_CONFIG;
    if (!config || !config.apiKey || config.apiKey.includes("PLACEHOLDER")) {
      console.warn("Firebase credentials are not configured in config.js. Falling back to local storage database mock.");
      return;
    }

    try {
      const { initializeApp } = await import('https://www.gstatic.com/firebasejs/10.8.0/firebase-app.js');
      const { getFirestore } = await import('https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js');
      firebaseApp = initializeApp(config);
      firestoreDb = getFirestore(firebaseApp);
      console.log("Firebase Firestore successfully initialized!");
    } catch (e) {
      console.error("Failed to initialize Firebase SDK:", e);
    }
  };

  const getInitialDB = () => {
    return {
      clients: [
        {
          id: "NXBTABC123",
          fullName: "Priya Patel",
          email: "priya@example.com",
          username: "priya",
          phone: "8282080783",
          address: "Mumbai, India",
          profession: "Software Engineer",
          dob: "1995-05-15",
          password: "user@123",
          walletBalance: 2450.75,
          walletProfit: 350.25,
          withdrawError: "",
          investments: [
            { id: "inv-1", planName: "Starter Yield", amount: 1000, date: "2026-07-01", status: "active" }
          ],
          withdrawals: [],
          registeredAt: new Date().toISOString(),
          loginHistory: [],
          lastLoginDate: new Date().toISOString()
        }
      ],
      settings: {
        platform_contact: "8282080783",
        platform_whatsapp: "8282080783",
        platform_upi_id: "xyz@okhdfc",
        platform_qr_code: ""
      },
      feedbacks: [
        {
          id: "fb-1",
          name: "Rohan S.",
          rating: 5,
          comment: "I started with the Starter Yield plan and have already withdrawn my first profits smoothly. Highly recommended!",
          date: "2026-07-10"
        },
        {
          id: "fb-2",
          name: "Neha M.",
          rating: 5,
          comment: "Very stable returns and prompt support channels. Setup my portfolio in minutes.",
          date: "2026-07-12"
        }
      ]
    };
  };

  const getMockDB = async () => {
    await initFirebase();
    if (firestoreDb) {
      try {
        const { doc, getDoc } = await import('https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js');
        const docRef = doc(firestoreDb, "nxtbillion_data", "db");
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
          const db = docSnap.data();
          if (db && db.clients) {
            localStorage.setItem("static_mock_db", JSON.stringify(db));
            return db;
          }
        } else {
          console.log("No database document found in Firestore. Creating new one with initial data.");
          const initialDB = getInitialDB();
          await saveMockDB(initialDB);
          return initialDB;
        }
      } catch (e) {
        console.warn("Failed to load from Firebase Firestore, falling back to localStorage", e);
      }
    }
    
    try {
      const dbStr = localStorage.getItem("static_mock_db");
      if (dbStr) {
        const parsed = JSON.parse(dbStr);
        if (parsed && parsed.clients) return parsed;
      }
    } catch(e) {}
    
    const initialDB = getInitialDB();
    localStorage.setItem("static_mock_db", JSON.stringify(initialDB));
    return initialDB;
  };
  
  const saveMockDB = async (db) => {
    localStorage.setItem("static_mock_db", JSON.stringify(db));
    await initFirebase();
    if (firestoreDb) {
      try {
        const { doc, setDoc } = await import('https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js');
        const docRef = doc(firestoreDb, "nxtbillion_data", "db");
        await setDoc(docRef, db);
        console.log("Database state successfully synchronized with Firebase cloud!");
      } catch (e) {
        console.error("Failed to sync database with Firebase cloud:", e);
      }
    }
  };

  const handleMockRequest = async (url, options) => {
    const db = await getMockDB();
    const method = (options?.method || "GET").toUpperCase();
    const body = options?.body ? JSON.parse(options.body) : null;
    
    let responseData = null;
    let status = 200;
    
    if (url.includes('/api/settings')) {
      if (method === "GET") {
        responseData = db.settings || {};
      } else if (method === "POST") {
        db.settings = { ...db.settings, ...body };
        saveMockDB(db);
        responseData = { success: true };
      }
    } else if (url.includes('/api/clients/bulk-save')) {
      db.clients = body;
      saveMockDB(db);
      responseData = { success: true };
    } else if (url.includes('/api/clients/')) {
      const parts = url.split('/api/clients/');
      const id = parts[parts.length - 1];
      if (method === "PUT") {
        const index = db.clients.findIndex(c => c.id === id);
        if (index !== -1) {
          db.clients[index] = { ...db.clients[index], ...body };
        } else {
          const newClient = {
            id,
            username: body.username || (body.email ? body.email.split('@')[0] : "user_" + Date.now()),
            fullName: body.fullName || "New Investor",
            email: body.email || "",
            phone: body.phone || "",
            address: body.address || "",
            profession: body.profession || "",
            dob: body.dob || "",
            password: body.password || body.phone || "user@123",
            walletBalance: body.walletBalance || 0,
            walletProfit: body.walletProfit || 0,
            withdrawError: body.withdrawError || "",
            investments: body.investments || [],
            withdrawals: body.withdrawals || [],
            registeredAt: body.registeredAt || new Date().toISOString(),
            loginHistory: body.loginHistory || [],
            lastLoginDate: body.lastLoginDate || new Date().toISOString()
          };
          db.clients.push(newClient);
        }
        saveMockDB(db);
        responseData = { success: true };
      } else if (method === "DELETE") {
        db.clients = db.clients.filter(c => c.id !== id);
        saveMockDB(db);
        responseData = { success: true };
      }
    } else if (url.includes('/api/clients')) {
      if (method === "GET") {
        responseData = db.clients || [];
      }
    } else if (url.includes('/api/login')) {
      const { email, password } = body;
      const client = db.clients.find(c => 
        (c.email.toLowerCase() === email.toLowerCase() || (c.username && c.username.toLowerCase() === email.toLowerCase())) &&
        c.password === password
      );
      if (client) {
        responseData = { success: true, client };
      } else {
        responseData = { success: false, message: 'Invalid email/username or password' };
      }
    } else if (url.includes('/api/check-user')) {
      const { email, username } = body;
      const emailExists = db.clients.some(c => c.email.toLowerCase() === email.toLowerCase());
      const usernameExists = db.clients.some(c => c.username && c.username.toLowerCase() === username.toLowerCase());
      if (emailExists || usernameExists) {
        responseData = { success: false, message: 'Email or Username is already registered!' };
      } else {
        responseData = { success: true };
      }
    } else if (url.includes('/api/signup')) {
      db.clients.push(body);
      saveMockDB(db);
      responseData = { success: true };
    } else if (url.includes('/api/feedbacks/')) {
      const parts = url.split('/api/feedbacks/');
      const id = parts[parts.length - 1];
      if (method === "DELETE") {
        db.feedbacks = db.feedbacks.filter(f => f.id !== id);
        saveMockDB(db);
        responseData = { success: true };
      }
    } else if (url.includes('/api/feedbacks')) {
      if (method === "GET") {
        responseData = db.feedbacks || [];
      } else if (method === "POST") {
        const newFb = {
          id: 'fb-' + Date.now(),
          name: body.name,
          rating: parseInt(body.rating) || 5,
          comment: body.comment,
          image: body.image,
          date: body.date || new Date().toISOString().substring(0, 10)
        };
        db.feedbacks.unshift(newFb);
        saveMockDB(db);
        responseData = newFb;
      }
    } else if (url.includes('/api/send-otp')) {
      const otp = Math.floor(100000 + Math.random() * 900000).toString();
      console.log("%c[OTP SIMULATOR] Generated OTP code is: " + otp, "color: #ff9900; font-weight: bold; font-size: 16px;");
      responseData = { success: true, otp, simulated: true };
    }
    
    return new Response(JSON.stringify(responseData), {
      status: status,
      headers: { 'Content-Type': 'application/json' }
    });
  };

  window.fetch = async function(url, options) {
    const urlStr = typeof url === 'string' ? url : (url?.url || '');
    const isApi = urlStr.includes('/api/');
    if (isApi) {
      const isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';
      if (isLocal) {
        try {
          const response = await originalFetch(url, options);
          if (response.ok || response.status !== 404) {
            return response;
          }
        } catch(e) {
          console.warn("Local Node server offline, falling back to client-side localStorage DB mock.", e);
        }
      }
      return handleMockRequest(urlStr, options);
    }
    return originalFetch(url, options);
  };
})();

// --- Antigravity Custom UID Generator ---
window.generateNXBTUid = () => {
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const digits = '0123456789';
  let randomLetters = '';
  let randomDigits = '';
  for (let i = 0; i < 3; i++) {
    randomLetters += letters.charAt(Math.floor(Math.random() * letters.length));
    randomDigits += digits.charAt(Math.floor(Math.random() * digits.length));
  }
  return 'NXBT' + randomLetters + randomDigits;
};

// --- Antigravity Custom Feedback Components ---
window.initFeedback = (u, j) => {
  if (window.FeedbackList) return;
  console.log("Initializing custom feedbacks frontend components...");

  window.FeedbackList = () => {
    const [feedbacks, setFeedbacks] = j.useState([]);
    const [name, setName] = j.useState("");
    const [rating, setRating] = j.useState(5);
    const [comment, setComment] = j.useState("");
    const [success, setSuccess] = j.useState(false);

    j.useEffect(() => {
      fetch("/api/feedbacks")
        .then(r => r.json())
        .then(data => setFeedbacks(data))
        .catch(err => console.error("Error loading feedbacks:", err));
    }, []);

    const handleSubmit = (e) => {
      e.preventDefault();
      if (!name.trim() || !comment.trim()) return;
      fetch("/api/feedbacks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, rating, comment, date: new Date().toISOString() })
      })
      .then(r => r.json())
      .then(newFb => {
        setFeedbacks(prev => [newFb, ...prev]);
        setName("");
        setComment("");
        setSuccess(true);
        setTimeout(() => setSuccess(false), 3000);
      })
      .catch(err => console.error("Error submitting feedback:", err));
    };

    return u.jsxs("div", {
      className: "space-y-6 animate-fade-in max-w-2xl mx-auto",
      children: [
        u.jsxs("div", {
          className: "bg-gradient-to-r from-blue-900 to-indigo-900 text-white p-6 rounded-3xl shadow-lg border border-blue-800",
          children: [
            u.jsx("h3", { className: "text-lg font-black tracking-wide text-amber-400", children: "Client Feedbacks" }),
            u.jsx("p", { className: "text-xs text-blue-200 mt-1", children: "See what our global investors say about Next Billion Technology." })
          ]
        }),
        u.jsxs("form", {
          onSubmit: handleSubmit,
          className: "bg-white p-5 rounded-3xl border border-slate-200 shadow-sm space-y-4 text-left",
          children: [
            u.jsx("h4", { className: "font-black text-slate-800 text-sm", children: "Share Your Feedback" }),
            success && u.jsx("div", { className: "bg-emerald-50 text-emerald-700 p-2.5 rounded-xl border border-emerald-250 text-xs font-bold text-center", children: "✓ Feedback submitted successfully!" }),
            u.jsxs("div", {
              className: "grid grid-cols-2 gap-3",
              children: [
                u.jsxs("div", {
                  className: "space-y-1",
                  children: [
                    u.jsx("label", { className: "text-[10px] text-slate-400 font-bold uppercase", children: "Your Name" }),
                    u.jsx("input", { required: true, type: "text", value: name, onChange: e => setName(e.target.value), className: "w-full border border-slate-200 rounded-xl px-3 py-2 text-xs font-semibold focus:outline-none focus:border-blue-500 bg-slate-50 text-slate-800", placeholder: "e.g. Rahul S." })
                  ]
                }),
                u.jsxs("div", {
                  className: "space-y-1",
                  children: [
                    u.jsx("label", { className: "text-[10px] text-slate-400 font-bold uppercase", children: "Rating" }),
                    u.jsx("select", { value: rating, onChange: e => setRating(parseInt(e.target.value)), className: "w-full border border-slate-200 rounded-xl px-3 py-2 text-xs font-semibold focus:outline-none focus:border-blue-500 bg-slate-50 text-slate-800", children: [5,4,3,2,1].map(r => u.jsx("option", { value: r, children: "★".repeat(r) + "☆".repeat(5-r) }, r)) })
                  ]
                })
              ]
            }),
            u.jsxs("div", {
              className: "space-y-1",
              children: [
                u.jsx("label", { className: "text-[10px] text-slate-400 font-bold uppercase", children: "Your Comments" }),
                u.jsx("textarea", { required: true, rows: 2, value: comment, onChange: e => setComment(e.target.value), className: "w-full border border-slate-200 rounded-xl px-3 py-2 text-xs font-semibold focus:outline-none focus:border-blue-500 bg-slate-50 text-slate-800", placeholder: "How has your investment journey been?" })
              ]
            }),
            u.jsx("button", { type: "submit", className: "w-full bg-[#0D47A1] hover:bg-blue-800 text-white font-extrabold text-xs py-2.5 rounded-xl transition-all active:scale-[0.98] cursor-pointer", children: "Submit Review" })
          ]
        }),
        u.jsx("div", {
          className: "space-y-4",
          children: feedbacks.map((fb, idx) => {
            if (fb.image) {
              return u.jsxs("div", {
                className: "bg-white p-3.5 rounded-3xl border border-slate-200 shadow-sm text-center space-y-2.5 animate-fade-in",
                children: [
                  u.jsx("img", { src: fb.image, className: "w-full rounded-2xl object-cover border border-slate-100 max-h-72", alt: "Feedback Proof" }),
                  u.jsxs("div", {
                    className: "flex justify-between items-center px-1 text-[10px] text-slate-400 font-bold",
                    children: [
                      fb.name && u.jsx("span", { className: "text-slate-700", children: fb.name }),
                      u.jsx("span", { className: "font-mono", children: fb.date ? fb.date.split("T")[0] : 'Recently' })
                    ]
                  })
                ]
              }, fb.id || idx);
            }
            
            const stars = "★".repeat(fb.rating || 5) + "☆".repeat(5 - (fb.rating || 5));
            return u.jsxs("div", {
              className: "bg-white p-4.5 rounded-3xl border border-slate-200 shadow-sm text-left space-y-2 animate-fade-in",
              children: [
                u.jsxs("div", {
                  className: "flex justify-between items-start",
                  children: [
                    u.jsxs("div", {
                      children: [
                        u.jsx("span", { className: "font-black text-slate-800 text-xs block", children: fb.name }),
                        u.jsx("span", { className: "text-amber-500 text-xs font-black tracking-wider block", children: stars })
                      ]
                    }),
                    u.jsx("span", { className: "text-[9px] text-slate-400 font-bold font-mono", children: fb.date ? fb.date.split("T")[0] : 'Recently' })
                  ]
                }),
                u.jsx("p", { className: "text-slate-600 text-xs leading-relaxed font-medium", children: fb.comment })
              ]
            }, fb.id || idx);
          })
        })
      ]
    });
  };

  window.FeedbackAdmin = () => {
    const [feedbacks, setFeedbacks] = j.useState([]);
    const [tab, setTab] = j.useState("comment"); // comment or image
    
    // Comment Form States
    const [name, setName] = j.useState("");
    const [rating, setRating] = j.useState(5);
    const [comment, setComment] = j.useState("");
    
    // Image Form States
    const [imgCaption, setImgCaption] = j.useState("");
    const [imgData, setImgData] = j.useState("");
    
    const [dateStr, setDateStr] = j.useState(() => new Date().toISOString().substring(0, 10));

    const loadFeedbacks = () => {
      fetch("/api/feedbacks")
        .then(r => r.json())
        .then(data => setFeedbacks(data))
        .catch(e => console.error("Error loading feedbacks in admin:", e));
    };

    j.useEffect(() => {
      loadFeedbacks();
    }, []);

    const handleAddComment = (e) => {
      e.preventDefault();
      if (!name.trim() || !comment.trim()) return;
      fetch("/api/feedbacks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, rating, comment, date: dateStr })
      })
      .then(r => r.json())
      .then(() => {
        loadFeedbacks();
        setName("");
        setComment("");
      })
      .catch(e => console.error("Error adding feedback comment:", e));
    };

    const handleAddImage = (e) => {
      e.preventDefault();
      if (!imgData) {
        alert("Please select/upload an image file first.");
        return;
      }
      fetch("/api/feedbacks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: imgCaption || "Earnings Proof", image: imgData, date: dateStr })
      })
      .then(r => r.json())
      .then(() => {
        loadFeedbacks();
        setImgCaption("");
        setImgData("");
        // Reset file input value
        const el = document.getElementById("fb-file-input");
        if (el) el.value = "";
      })
      .catch(e => console.error("Error adding feedback image:", e));
    };

    const handleFileChange = (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onloadend = () => {
        setImgData(reader.result);
      };
      reader.readAsDataURL(file);
    };

    const handleDelete = (id) => {
      if (!confirm("Are you sure you want to delete this feedback?")) return;
      fetch(`/api/feedbacks/${id}`, { method: "DELETE" })
        .then(r => r.json())
        .then(() => loadFeedbacks())
        .catch(e => console.error("Error deleting feedback in admin:", e));
    };

    return u.jsxs("div", {
      className: "space-y-4",
      children: [
        u.jsx("span", { className: "text-[10px] font-black text-slate-400 block border-b pb-1", children: "=== CONTROL FEEDBACKS ===" }),
        
        // Tab switcher inside add form
        u.jsxs("div", {
          className: "flex bg-slate-100 p-1 rounded-xl gap-1 shrink-0",
          children: [
            u.jsx("button", { type: "button", onClick: () => setTab("comment"), className: `flex-grow py-1.5 rounded-lg text-[10px] font-black transition-all cursor-pointer ${tab==="comment"?"bg-white text-slate-800 shadow-sm":"text-slate-450 hover:text-slate-700"}`, children: "User Comment" }),
            u.jsx("button", { type: "button", onClick: () => setTab("image"), className: `flex-grow py-1.5 rounded-lg text-[10px] font-black transition-all cursor-pointer ${tab==="image"?"bg-white text-slate-800 shadow-sm":"text-slate-450 hover:text-slate-700"}`, children: "Upload Image" })
          ]
        }),

        // Form 1: Add Comment
        tab === "comment" && u.jsxs("form", {
          onSubmit: handleAddComment,
          className: "bg-white p-4 rounded-xl border border-slate-200 space-y-3 text-slate-800",
          children: [
            u.jsx("h4", { className: "text-xs font-black text-slate-800 uppercase", children: "Add Fake Feedback / Review" }),
            u.jsxs("div", {
              className: "grid grid-cols-2 gap-2",
              children: [
                u.jsxs("div", {
                  children: [
                    u.jsx("label", { className: "text-[8px] text-slate-400 font-bold uppercase block", children: "Name" }),
                    u.jsx("input", { type: "text", required: true, value: name, onChange: e => setName(e.target.value), className: "w-full border border-slate-200 rounded-lg p-1 text-xs outline-none focus:border-blue-500 bg-slate-50 text-slate-900 font-semibold", placeholder: "Rohan S." })
                  ]
                }),
                u.jsxs("div", {
                  children: [
                    u.jsx("label", { className: "text-[8px] text-slate-400 font-bold uppercase block", children: "Rating" }),
                    u.jsx("select", { value: rating, onChange: e => setRating(parseInt(e.target.value)), className: "w-full border border-slate-200 rounded-lg p-1 text-xs outline-none bg-slate-50 text-slate-900 font-semibold", children: [5,4,3,2,1].map(r => u.jsx("option", { value: r, children: "★".repeat(r) }, r)) })
                  ]
                })
              ]
            }),
            u.jsxs("div", {
              className: "grid grid-cols-2 gap-2",
              children: [
                u.jsxs("div", {
                  className: "col-span-2",
                  children: [
                    u.jsx("label", { className: "text-[8px] text-slate-400 font-bold uppercase block", children: "Date" }),
                    u.jsx("input", { type: "date", value: dateStr, onChange: e => setDateStr(e.target.value), className: "w-full border border-slate-200 rounded-lg p-1 text-xs outline-none focus:border-blue-500 bg-slate-50 text-slate-900 font-semibold" })
                  ]
                })
              ]
            }),
            u.jsxs("div", {
              children: [
                u.jsx("label", { className: "text-[8px] text-slate-400 font-bold uppercase block", children: "Comment" }),
                u.jsx("textarea", { required: true, value: comment, onChange: e => setComment(e.target.value), className: "w-full border border-slate-200 rounded-lg p-1 text-xs outline-none focus:border-blue-500 bg-slate-50 text-slate-900 font-medium", placeholder: "Excellent platform...", rows: 2 })
              ]
            }),
            u.jsx("button", { type: "submit", className: "w-full py-1.5 bg-blue-600 text-white rounded-lg font-bold text-xs hover:bg-blue-700 transition-colors cursor-pointer", children: "Add Feedback Comment" })
          ]
        }),

        // Form 2: Upload Image
        tab === "image" && u.jsxs("form", {
          onSubmit: handleAddImage,
          className: "bg-white p-4 rounded-xl border border-slate-200 space-y-3 text-slate-800",
          children: [
            u.jsx("h4", { className: "text-xs font-black text-slate-800 uppercase", children: "Upload Feedback Image (e.g. Screenshot)" }),
            u.jsxs("div", {
              className: "grid grid-cols-2 gap-2",
              children: [
                u.jsxs("div", {
                  children: [
                    u.jsx("label", { className: "text-[8px] text-slate-400 font-bold uppercase block", children: "Name / Caption" }),
                    u.jsx("input", { type: "text", value: imgCaption, onChange: e => setImgCaption(e.target.value), className: "w-full border border-slate-200 rounded-lg p-1 text-xs outline-none focus:border-blue-500 bg-slate-50 text-slate-900 font-semibold", placeholder: "e.g. Amit's Proof" })
                  ]
                }),
                u.jsxs("div", {
                  children: [
                    u.jsx("label", { className: "text-[8px] text-slate-400 font-bold uppercase block", children: "Date" }),
                    u.jsx("input", { type: "date", value: dateStr, onChange: e => setDateStr(e.target.value), className: "w-full border border-slate-200 rounded-lg p-1 text-xs outline-none focus:border-blue-500 bg-slate-50 text-slate-900 font-semibold" })
                  ]
                })
              ]
            }),
            u.jsxs("div", {
              children: [
                u.jsx("label", { className: "text-[8px] text-slate-400 font-bold uppercase block", children: "Choose Image File" }),
                u.jsx("input", { id: "fb-file-input", type: "file", accept: "image/*", required: true, onChange: handleFileChange, className: "w-full border border-slate-200 rounded-lg p-1 text-xs outline-none bg-slate-50 text-slate-900 font-semibold" })
              ]
            }),
            imgData && u.jsxs("div", {
              className: "space-y-1 text-center",
              children: [
                u.jsx("span", { className: "text-[8px] text-slate-400 block font-bold", children: "PREVIEW:" }),
                u.jsx("img", { src: imgData, className: "max-h-24 mx-auto border rounded-lg shadow-sm" })
              ]
            }),
            u.jsx("button", { type: "submit", className: "w-full py-1.5 bg-blue-600 text-white rounded-lg font-bold text-xs hover:bg-blue-700 transition-colors cursor-pointer", children: "Upload Image Feedback" })
          ]
        }),

        // List of feedbacks
        u.jsx("div", {
          className: "space-y-2",
          children: feedbacks.map((fb, idx) => u.jsxs("div", {
            className: "bg-white p-3 rounded-lg border border-slate-200 flex justify-between items-start gap-2 text-slate-800",
            children: [
              u.jsxs("div", {
                className: "space-y-1 text-xs text-slate-700 text-left flex-grow",
                children: [
                  u.jsxs("div", {
                    className: "flex items-center gap-2",
                    children: [
                      u.jsx("span", { className: "font-black text-slate-900", children: fb.name }),
                      !fb.image && u.jsx("span", { className: "text-amber-500 font-bold", children: "★".repeat(fb.rating || 5) }),
                      u.jsx("span", { className: "text-[8px] text-slate-400 font-mono", children: fb.date ? fb.date.split("T")[0] : 'Recently' })
                    ]
                  }),
                  fb.image ? u.jsx("img", { src: fb.image, className: "max-h-16 rounded border shadow-sm mt-1" }) : u.jsx("p", { className: "text-slate-600 leading-normal font-medium", children: fb.comment })
                ]
              }),
              u.jsx("button", { type: "button", onClick: () => handleDelete(fb.id), className: "text-red-500 hover:text-red-700 text-[10px] font-black uppercase cursor-pointer shrink-0", children: "Del" })
            ]
          }, fb.id || idx))
        })
      ]
    });
  };
};

